-- Appareils d'un utilisateur, pour les notifications push.
--
-- A lancer une fois sur une base existante. Les installations neuves la
-- recoivent par le schema complet, ou Hibernate la cree au demarrage puisque
-- ddl-auto vaut update ; le script explicite evite de dependre de ce hasard et
-- porte les contraintes qu'Hibernate ne poserait pas toutes.
--
--   psql -U postgres -d musical_app -f user_devices.sql

CREATE TABLE IF NOT EXISTS "user_devices" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,

  -- Unique sur le jeton seul, et non sur le couple (utilisateur, jeton).
  -- Un meme telephone sert a plusieurs comptes : a la reconnexion, le jeton
  -- doit CHANGER de proprietaire. Sans cette contrainte, l'ancien compte
  -- continuerait de recevoir les notifications sur un telephone qui n'est
  -- plus le sien.
  "token" VARCHAR(512) UNIQUE NOT NULL,

  -- ANDROID ou IOS. Chaine et non table de reference : deux valeurs qui ne
  -- bougeront pas ne valent pas une jointure, et la validation est faite a
  -- l'entree.
  "platform" VARCHAR(16) NOT NULL,

  "created_at" TIMESTAMP NOT NULL,

  -- Mis a jour a chaque reenregistrement. Sert a purger les appareils qu'on
  -- n'a plus vus depuis longtemps : un jeton FCM finit par etre revoque, et
  -- la table grossirait indefiniment sans cela.
  "last_seen_at" TIMESTAMP NOT NULL,

  FOREIGN KEY ("user_id") REFERENCES "users" ("id")
);

-- L'envoi cherche toujours les appareils d'un utilisateur donne.
CREATE INDEX IF NOT EXISTS "idx_user_devices_user" ON "user_devices" ("user_id");

SELECT count(*) AS appareils_enregistres FROM user_devices;
